script:
// Mounts the portable dashboard driver (whatsapp.ui.DashboardBlock) on this block.
const mount = root_element.querySelector(".whatsapp-dashboard");
if (mount && window.whatsapp && whatsapp.ui && typeof whatsapp.ui.DashboardBlock === "function") {
	new whatsapp.ui.DashboardBlock({
		wrapper: mount,
		number_cards: ["WA Queued Now", "WA Connected Devices", "WA Sent Today", "WA Failed Today"],
		charts: ["WA Messages per Day", "WA Outbound by Status"],
		period_filter: true,
		refresh_seconds: 120,
		events: { "wa:queue:progress": true, "wa:message:status": true, "wa:device:status": true },
	});
} else if (mount) {
	mount.textContent = __("The dashboard kit is not loaded.");
}
